    return out
def plane_angle(M,B):
    m=B.T@M@B; r=np.hypot(m[0,0]+m[1,1], m[1,0]-m[0,1])/2
    return np.degrees(np.arctan2(m[1,0]-m[0,1], m[0,0]+m[1,1])), r, np.linalg.norm(m)
